import{R as t,e as n,f as o,U as i}from"./chunks/framework.ywem4qy5.js";const k=JSON.parse('{"title":"Zendesk","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/help-desk/zendesk.md","filePath":"integrations/help-desk/zendesk.md","lastUpdated":1775908585000}'),s={name:"integrations/help-desk/zendesk.md"};function r(a,e,l,d,h,g){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="zendesk" tabindex="-1">Zendesk <a class="header-anchor" href="#zendesk" aria-label="Permalink to &quot;Zendesk&quot;">​</a></h1><p>Follow the below steps to connect to the Zendesk API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Help Desk</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Zendesk</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-zendesk-api" tabindex="-1">Step 2. Connect to the Zendesk API <a class="header-anchor" href="#step-2-connect-to-the-zendesk-api" aria-label="Permalink to &quot;Step 2. Connect to the Zendesk API&quot;">​</a></h3><ol><li>Go to <a href="https://www.zendesk.com" target="_blank">Zendesk</a> and log in to your account.</li><li>In the left-hand sidebar, click the <strong>Settings</strong> icon.</li><li>Click the <strong>Go to Admin Center</strong> link.</li><li>In the left-hand sidebar select <strong>Apps and Integrations</strong> → <strong>Zendesk API</strong>.</li><li>Ensure that <strong>Token Access</strong> is enabled.</li><li>Click the <strong>Add API Token</strong> button.</li><li>Copy the <strong>API Key</strong> from Zendesk and paste in the <strong>API Key</strong> field in Formie.</li><li>Enter the full domain (including <code>https://</code>) for your Zendesk account in the <strong>Domain</strong> field in Formie.</li><li>Enter your Zendesk <strong>login email</strong> (the same one used to generate the token) in the <strong>Username</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar to verify the connection.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=t(s,[["render",r]]);export{k as __pageData,p as default};
